package org.rabochaya.maptests;
import android.content.*;import java.util.*;import java.lang.reflect.*;import org.json.*;
/** Named stacks use the existing layer scenarios and actual force-stop handoff. */
final class CompositionPresetChecks {
 final MapAndroidChecks m;final MapLayersChecks layers;final ManagerVisualChecks visual;
 CompositionPresetChecks(MapAndroidChecks m,MapLayersChecks layers){this.m=m;this.layers=layers;visual=new ManagerVisualChecks(m);}
 Object library(long id)throws Exception{return m.staticCall("MapCompositionSettings","loadPresets",new Class[]{Context.class,long.class},m.getTargetContext(),id);}
 Object model(Object library)throws Exception{return layers.f(library,"presets");}
 byte[] bytes(Object library)throws Exception{return (byte[])m.call(model(library),"encode",new Class[]{});}
 List entries(Object library)throws Exception{return (List)layers.f(model(library),"entries");}
 Object save(long id,Object library,Object composition,String name)throws Exception{return m.staticCall("MapCompositionSettings","savePreset",new Class[]{Context.class,long.class,m.owned("MapCompositionSettings$PresetsSnapshot"),m.owned("MapCompositionSettings$Snapshot"),String.class},m.getTargetContext(),id,library,composition,name);}
 Object delete(long id,Object library,String name)throws Exception{return m.staticCall("MapCompositionSettings","deletePreset",new Class[]{Context.class,long.class,m.owned("MapCompositionSettings$PresetsSnapshot"),String.class},m.getTargetContext(),id,library,name);}
 void open(String name,String action)throws Exception{m.click("Наборы слоёв");m.click(name);m.click(action);}
 void run(Object store,long id,long other)throws Exception{Context c=m.getTargetContext();String name="QA_Набор 😀";byte[] original=layers.encoded(layers.model());boolean enabled=(Boolean)layers.f(layers.snapshot(),"enabled");SharedPreferences preferences=c.getSharedPreferences("map-compositions",0);Map<String,?> before=new HashMap<>(preferences.getAll());
  m.click("Наборы слоёв");m.click("Сохранить показанный состав");m.inputs(name);visual.keyboard();visual.snapshot("layers-preset-name",true);m.click("Отмена");m.check(before.equals(preferences.getAll())&&Arrays.equals(original,layers.encoded(layers.model())),"preset name Cancel never creates settings or alters current composition");
  m.click("Наборы слоёв");m.click("Сохранить показанный состав");m.inputs(name);m.click("Сохранить");m.waitText("Набор сохранён");m.check(Arrays.equals(original,layers.encoded(layers.model()))&&enabled==(Boolean)layers.f(layers.snapshot(),"enabled"),"Save named set does not apply it or change current settings");Object saved=library(id);byte[] named=bytes(saved);m.check(entries(saved).size()==1&&name.equals(layers.f(entries(saved).get(0),"name"))&&Arrays.equals(original,layers.encoded(layers.f(entries(saved).get(0),"composition"))),"named set stores exact ordered IDs/visibility/opacity/source metadata");
  m.click("Наборы слоёв");m.click("Сохранить показанный состав");m.inputs(name);m.click("Сохранить");m.check(Arrays.equals(named,bytes(library(id))),"duplicate name refuses without overwriting previous set");m.click("Отмена");m.click("Наборы слоёв");m.waitText(name);visual.snapshot("layers-preset-list",false);m.click(name);m.click("Удалить набор");m.click("Отмена");m.check(Arrays.equals(named,bytes(library(id)))&&Arrays.equals(original,layers.encoded(layers.model())),"delete confirmation Cancel preserves set and current composition");
  m.click("Наборы слоёв");m.click(name);Object newer=save(id,library(id),layers.snapshot(),"QA_TEMP");byte[] newerBytes=bytes(newer);m.click("Удалить набор");m.click("Удалить");m.waitText("Наборы изменились");m.check(Arrays.equals(newerBytes,bytes(library(id))),"stale delete cannot remove entries from replaced library");open("QA_TEMP","Удалить набор");m.click("Удалить");m.waitText("Набор удалён");m.check(entries(library(id)).size()==1&&Arrays.equals(original,layers.encoded(layers.model())),"explicit Delete drops only selected preset, preserving current stack");
  open(name,"Применить набор");Object old=layers.snapshot(),composition=layers.model();String layerId=(String)layers.f(((List)layers.f(composition,"layers")).get(0),"id");Object changed=m.call(composition,"opacity",new Class[]{String.class,int.class},layerId,1);Object changedSnapshot=m.staticCall("MapCompositionSettings","save",new Class[]{Context.class,long.class,m.owned("MapCompositionSettings$Snapshot"),m.owned("MapComposition"),boolean.class},c,id,old,changed,true);byte[] changedBytes=layers.encoded(layers.f(changedSnapshot,"composition"));m.click("Применить");m.waitText("Состав изменился");m.check(Arrays.equals(changedBytes,layers.encoded(layers.f(layers.stored(id),"composition"))),"stale apply cannot overwrite newer composition");
  open(name,"Применить набор");m.click("Применить");m.waitText("Набор применён");m.check((Boolean)layers.f(layers.snapshot(),"enabled")&&Arrays.equals(original,layers.encoded(layers.model())),"explicit apply restores exact stack and enables composition");
  before=new HashMap<>(preferences.getAll());boolean foreign=false;try{m.staticCall("MapCompositionSettings","applyPreset",new Class[]{Context.class,long.class,m.owned("MapCompositionSettings$Snapshot"),m.owned("MapCompositionSettings$PresetsSnapshot"),String.class},c,other,layers.stored(other),library(id),name);}catch(InvocationTargetException e){foreign=e.getCause() instanceof java.io.IOException;}m.check(foreign&&before.equals(preferences.getAll()),"foreign project library refuses without touching either project settings");
  long deleted=new GeometryConfirmationChecks(m).fixture(store,false);try{Object oldComposition=layers.stored(deleted),oldLibrary=library(deleted);m.call(store,"remove",new Class[]{long.class},deleted);before=new HashMap<>(preferences.getAll());boolean refused=false;try{save(deleted,oldLibrary,oldComposition,"QA_DELETED");}catch(InvocationTargetException e){refused=e.getCause() instanceof java.io.IOException;}m.check(refused&&before.equals(preferences.getAll()),"deleted owner cannot resurrect private preset metadata");}finally{m.call(store,"remove",new Class[]{long.class},deleted);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},c,deleted);}
  saved=library(id);c.getSharedPreferences("qa_layers",0).edit().putString("preset_name",name).putString("presets",android.util.Base64.encodeToString(bytes(saved),android.util.Base64.NO_WRAP)).commit();visual.emit("COMPOSITION_PRESETS save/cancel/duplicate/deleteCancel/staleLibrary/staleComposition/apply/foreign/deletedOwner PASS");
 }
 void reopen(long id)throws Exception{SharedPreferences handoff=m.getTargetContext().getSharedPreferences("qa_layers",0);String name=handoff.getString("preset_name","");Object saved=library(id);m.check(!name.isEmpty()&&entries(saved).size()==1&&Arrays.equals(bytes(saved),android.util.Base64.decode(handoff.getString("presets",""),android.util.Base64.NO_WRAP)),"named library/revision/stack exact after real force-stop");byte[] composition=layers.encoded(layers.model()),sets=bytes(saved);open(name,"Применить набор");m.click("Отмена");m.check(Arrays.equals(composition,layers.encoded(layers.model()))&&Arrays.equals(sets,bytes(library(id))),"restarted preset Apply Cancel performs no implicit change");open(name,"Удалить набор");m.click("Удалить");m.waitText("Набор удалён");m.check(entries(library(id)).isEmpty()&&Arrays.equals(composition,layers.encoded(layers.model())),"explicit Delete of last restored set preserves active layers");visual.emit("COMPOSITION_PRESETS_REOPEN PASS");}
}
